let _idx = 0;
function readln() { return _lines[_idx++]; }
function readint() { return parseInt(readln()); }
function readlong() { return BigInt(readln().trim()); }
function readdouble() { return parseFloat(readln()); }
function readstrings() { return readln().trim().split(' '); }
