let mod = 998244353n;

function pw(a, b) {
    let c = b;
    let d = a;
    let res = 1n;
    while (c > 0n) {
        if ((c & 1n) !== 0n) {
            res *= d;
            res %= mod;
        }
        d *= d;
        d %= mod;
        c /= 2n;
    }
    return res;
}

function inv(a) {
    return pw(a, mod - 2n);
}

function main() {
    let tt = 1;
    let f = new Array(500010).fill(1n);
    for (let i = 2; i <= 500000; i++) {
        f[i] = (f[i - 1] * BigInt(i)) % mod;
    }
    let output = [];
